  arena_ = allocator->Allocate<uint8_t>(0);
  for (size_t i = 0; i < 35; ++i) reinterpret_cast<uint32_t*>(arena_)[i] = 0;
  MicroFreakVirtualAnalogVCFEngine::Init(allocator);

}
